mod solution;

fn main() {
    let cases = [
    (r#"values=[1,2,3,4,5,6]"#, r#"27"#),
    (r#"values=[0,0,0,0,0,0]"#, r#"9"#),
    (r#"
values=[0,0,0,0,0,0]
"#, r#"9"#),
    (r#"  
values=[1,2,3,4,5,6]
  "#, r#"27"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS lazy-segment-tree");
}
